/**
 * Only resize URLs generated by our known QR renderer. Supplier URLs may be
 * signed, so even adding an innocent query parameter can invalidate them.
 */
export function qrImageUrl(source: string, size: number): string {
  try {
    const url = new URL(source);
    if (
      url.origin !== "https://api.qrserver.com" ||
      url.pathname !== "/v1/create-qr-code/" ||
      !url.searchParams.has("data") ||
      [...url.searchParams.keys()].some(key => !["data", "size", "margin"].includes(key))
    ) return source;
    url.searchParams.set("size", `${size}x${size}`);
    url.searchParams.set("margin", "1");
    return url.toString();
  } catch {
    return source;
  }
}
